class Solution {
    public boolean isPossibleDivide(int[] nums,int k){
        if(nums.length%k!=0)return false;
        TreeMap<Integer,Integer> frequency=new TreeMap<>();
        for(int value:nums)frequency.merge(value,1,Integer::sum);
        while(!frequency.isEmpty()){
            int start=frequency.firstKey();
            for(int value=start;value<start+k;value++){
                Integer count=frequency.get(value);
                if(count==null)return false;
                if(count==1)frequency.remove(value);
                else frequency.put(value,count-1);
            }
        }
        return true;
    }
}

code.kotlin:
class Solution {
    fun isPossibleDivide(nums:IntArray,k:Int):Boolean{
        if(nums.size%k!=0)return false;
        val frequency=java.util.TreeMap<Int,Int>();
        for(value in nums)frequency[value]=(frequency[value]?:0)+1;
        while(frequency.isNotEmpty()){
            val start=frequency.firstKey();
            for(value in start until start+k){
                val count=frequency[value]?:return false;
                if(count==1)frequency.remove(value)else frequency[value]=count-1
            }
        };
        return true
    }
}

